    // Helper function to calculate the total number of characters in a list of strings
    function sumChars(lst: seq<string>): int {
        var total: int := 0;
        var i: int := 0;
        while (i < |lst|)
            invariant 0 <= i <= |lst| // i is within bounds
            invariant total == SeqSum(lst, i) // total is the sum of lengths of lst[0..i)
        {
            total := total + |lst[i]|;
            i := i + 1;
        }
        total
    }

    // Helper function to compute the sum of lengths of strings in the sequence up to index n
    function SeqSum(lst: seq<string>, n: int): int {
        if n == 0 then 0 else |lst[n-1]| + SeqSum(lst, n-1)
    }

